long compressTimeBucket(long timeBucket, int dayStep) {
    int dayOfMonth = (int) (timeBucket % 100);
    int month = (int) ((timeBucket / 100) % 100);
    int year = (int) (timeBucket / 10000);

    // Calculate the new day of the month
    int newDayOfMonth = ((dayOfMonth - 1) / dayStep) * dayStep + 1;

    // Reconstruct the time bucket
    return year * 10000 + month * 100 + newDayOfMonth;
}

long compressTimeBucket(long timeBucket, int dayStep) {
    int dayOfMonth = (int) (timeBucket % 100);
    int month = (int) ((timeBucket / 100) % 100);
    int year = (int) (timeBucket / 10000);

    int adjustedDay = (dayOfMonth - 1) / dayStep * dayStep + 1;
    if (adjustedDay < 1 || adjustedDay > 31) {
        throw new IllegalArgumentException("Invalid day of month: " + dayOfMonth);
    }

    return year * 10000 + month * 100 + adjustedDay;
}

long function(long timeBucket, int dayStep) {  
    int year = (int) (timeBucket / 10000);  
    int month = (int) ((timeBucket / 100) % 100);  
    int day = (int) (timeBucket % 100);  
    int adjustedDay = ((day - 1) / dayStep) * dayStep + 1;  
    return year * 10000 + month * 100 + adjustedDay;  
}

int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int size = 0;
    for (int i = index; i < index + len; i++) {
        char c = str.charAt(i);
        if (c <= 0x7F) {
            size++;
        } else if (c <= 0x7FF) {
            size += 2;
        } else if (Character.isHighSurrogate(c) && i + 1 < index + len && Character.isLowSurrogate(str.charAt(i + 1))) {
            size += 4;
            i++; // skip the low surrogate as it's processed with the high surrogate
        } else {
            size += 3;
        }
    }
    return size;
}

