private void pop(final String descriptor){
    // Assuming the descriptor is in a format similar to JVM type descriptors
    // and that we have a stack to manipulate.
    if (descriptor == null || descriptor.isEmpty()) {
        return;
    }

    int index = 0;
    while (index < descriptor.length()) {
        char c = descriptor.charAt(index);
        switch (c) {
            case 'V': // void
                // Do nothing for void descriptor in a method signature
                break;
            case 'B': // byte
            case 'C': // char
            case 'D': // double
            case 'F': // float
            case 'I': // int
            case 'J': // long
            case 'S': // short
            case 'Z': // boolean
                // Pop one element from the stack for each primitive type
                stack.pop();
                index++;
                break;
            case 'L': // reference types
                // Pop one element from the stack for reference types
                stack.pop();
                // Move index to the end of the class descriptor (skipping ';')
                while (descriptor.charAt(index) != ';') {
                    index++;
                }
                index++; // Move past ';'
                break;
            case '[': // array types
                // Pop one element from the stack for array types
                stack.pop();
                // Move index to the end of the array descriptor
                while (descriptor.charAt(index) == '[') {
                    index++;
                }
                // Handle the type of the array
                if (descriptor.charAt(index) == 'L') {
                    // Reference type array
                    // Move index to the end of the class descriptor (skipping ';')
                    while (descriptor.charAt(index) != ';') {
                        index++;
                    }
                    index++; // Move past ';'
                } else {
                    // Primitive type array
                    index++;
                }
                break;
            case '(': // method descriptor starts
                // Skip '('
                index++;
                // Process arguments
                while (descriptor.charAt(index) != ')') {
                    // Recursively pop argument types
                    pop(String.valueOf(descriptor.charAt(index)));
                    index++;
                }
                // Skip ')'
                index++;
                // Return type is ignored as it is not popped
                return;
            default:
                // Unknown type, do nothing
                index++;
                break;
        }
    }
}

