    int numArgs = 0;
    if (descriptor.charAt(0) == '(') {
        // It's a method descriptor, count the number of arguments
        int i = 1; // skip the '('
        while (descriptor.charAt(i) != ')') {
            char c = descriptor.charAt(i);
            if (c == 'L' || c == '[') {
                // Skip the entire object or array type descriptor
                while (descriptor.charAt(i) != ';') {
                    i++;
                }
                i++; // skip the ';'
            } else {
                i++;
            }
            numArgs++;
        }
    } else {
        // It's a single type descriptor
        numArgs = 1;
    }
    // Pop the types from the stack
    for (int j = 0; j < numArgs; j++) {
        outputFrameStack.pop();
    }
}

