String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }

    StringBuilder output = new StringBuilder();
    int length = str.length();
    for (int i = 0; i < length; i++) {
        char currentChar = str.charAt(i);
        if (currentChar == '\\') {
            // Check if it's the last character or the next character is not an escape sequence
            if (i == length - 1) {
                output.append(currentChar);
                break;
            }
            char nextChar = str.charAt(i + 1);
            switch (nextChar) {
                case 'n':
                    output.append('\n');
                    break;
                case 'r':
                    output.append('\r');
                    break;
                case 't':
                    output.append('\t');
                    break;
                case 'b':
                    output.append('\b');
                    break;
                case 'f':
                    output.append('\f');
                    break;
                case '\\':
                    output.append('\\');
                    break;
                case '\'':
                    output.append('\'');
                    break;
                case '\"':
                    output.append('\"');
                    break;
                default:
                    output.append(currentChar);
                    output.append(nextChar);
                    break;
            }
            i++; // Skip the next character as it is part of the escape sequence
        } else {
            output.append(currentChar);
        }
    }
    return output.toString();
}

