String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder result = new StringBuilder();
    int i = 0;
    while (i < str.length()) {
        char c = str.charAt(i);
        if (c == '\\') {
            i++;
            if (i >= str.length()) {
                throw new Exception("Invalid escape sequence");
            }
            c = str.charAt(i);
            switch (c) {
                case 'b':
                    result.append('\b');
                    break;
                case 't':
                    result.append('\t');
                    break;
                case 'n':
                    result.append('\n');
                    break;
                case 'f':
                    result.append('\f');
                    break;
                case 'r':
                    result.append('\r');
                    break;
                case '"':
                    result.append('\"');
                    break;
                case '\'':
                    result.append('\'');
                    break;
                case '\\':
                    result.append('\\');
                    break;
                case 'u':
                    if (i + 4 >= str.length()) {
                        throw new Exception("Invalid Unicode escape sequence");
                    }
                    String hex = str.substring(i + 1, i + 5);
                    try {
                        result.append((char) Integer.parseInt(hex, 16));
                    } catch (NumberFormatException e) {
                        throw new Exception("Invalid Unicode hex value: " + hex);
                    }
                    i += 4;
                    break;
                default:
                    throw new Exception("Invalid escape sequence");
            }
        } else {
            result.append(c);
        }
        i++;
    }
    return result.toString();
}

