protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    List<E> edgeList = new ArrayList<>(tour);
    if (edgeList.isEmpty()) {
        return new GraphPathImpl<>(graph, null, 0.0);
    }

    V startVertex = graph.getEdgeSource(edgeList.get(0));
    List<V> vertexList = new ArrayList<>();
    vertexList.add(startVertex);

    while (!edgeList.isEmpty()) {
        E nextEdge = null;
        for (E edge : edgeList) {
            if (graph.getEdgeSource(edge).equals(vertexList.get(vertexList.size() - 1))) {
                nextEdge = edge;
                break;
            }
        }
        if (nextEdge == null) {
            break;
        }
        vertexList.add(graph.getEdgeTarget(nextEdge));
        edgeList.remove(nextEdge);
    }

    return new GraphPathImpl<>(graph, vertexList, calculatePathWeight(vertexList, graph));
}

private double calculatePathWeight(List<V> vertexList, Graph<V, E> graph) {
    double weight = 0.0;
    for (int i = 0; i < vertexList.size() - 1; i++) {
        weight += graph.getEdgeWeight(graph.getEdge(vertexList.get(i), vertexList.get(i + 1)));
    }
    // Add weight of the edge connecting the last vertex back to the start vertex
    weight += graph.getEdgeWeight(graph.getEdge(vertexList.get(vertexList.size() - 1), vertexList.get(0)));
    return weight;
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    List<E> edgeList = new ArrayList<>(tour);
    V startVertex = edgeList.isEmpty() ? null : graph.getEdgeSource(edgeList.get(0));
    List<V> vertexList = new ArrayList<>();
    if (startVertex != null) {
        vertexList.add(startVertex);
        V currentVertex = startVertex;
        for (E edge : edgeList) {
            V targetVertex = graph.getEdgeTarget(edge);
            if (!vertexList.contains(targetVertex)) {
                vertexList.add(targetVertex);
                currentVertex = targetVertex;
            }
        }
    }
    return new DefaultGraphPath<>(graph, vertexList, edgeList);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    List<E> edgeList = new ArrayList<>(tour);
    V source = graph.getEdgeSource(edgeList.get(0));
    V current = source;
    List<E> pathEdges = new ArrayList<>();
    Set<E> visitedEdges = new HashSet<>();

    while (!visitedEdges.equals(tour)) {
        for (E edge : edgeList) {
            if (!visitedEdges.contains(edge) && graph.getEdgeSource(edge).equals(current)) {
                pathEdges.add(edge);
                visitedEdges.add(edge);
                current = graph.getEdgeTarget(edge);
                break;
            }
        }
    }

    return new GraphPathImpl<>(graph, source, current, pathEdges, (double) pathEdges.size());
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    List<E> edgeList = new ArrayList<>(tour);
    V startVertex = edgeList.get(0).getSource();
    List<V> vertexList = new ArrayList<>();
    vertexList.add(startVertex);

    V currentVertex = startVertex;
    while (!edgeList.isEmpty()) {
        for (Iterator<E> it = edgeList.iterator(); it.hasNext(); ) {
            E edge = it.next();
            V source = edge.getSource();
            V target = edge.getTarget();
            if (source.equals(currentVertex) || target.equals(currentVertex)) {
                vertexList.add(source.equals(currentVertex) ? target : source);
                currentVertex = source.equals(currentVertex) ? target : source;
                it.remove();
                break;
            }
        }
    }

    return new GraphWalk<>(graph, startVertex, currentVertex, vertexList, edgeList, 0);
}

