        if (types[i] == NAME_TYPE) {  
            Pair<String, String> existingEntry = (Pair<String, String>) constantPool[i];  
            if (existingEntry.getFirst().equals(name) && existingEntry.getSecond().equals(descriptor)) {  
                return i;  
