int addConstantNameAndType(final String name, final String descriptor) {
    for (int i = 1; i < maxPoolSize; i++) {
        if (types[i] == NAME_TYPE && utf8s[offsets[i]] == name && utf8s[offsets[i] + 1] == descriptor) {
            return i;
        }
    }
    // Assuming appendNameAndType adds the new constant and returns its index
    return appendNameAndType(name, descriptor);
}

int addConstantNameAndType(final String name, final String descriptor) {
    for (int i = 1; i < maxPoolSize; i++) {
        if (types[i] == NAME_TYPE) {
            int[] nameAndType = (int[]) objects[i];
            if (utf8s[nameAndType[0]].equals(name) && utf8s[nameAndType[1]].equals(descriptor)) {
                return i;
            }
        }
    }
    if (ensureCapacity(maxPoolSize + 1)) {
        int name_index = addConstantUtf8(name);
        int descriptor_index = addConstantUtf8(descriptor);
        objects[maxPoolSize] = new int[]{name_index, descriptor_index};
        types[maxPoolSize++] = NAME_TYPE;
    }
    return maxPoolSize - 1;
}

