String applyRelativePath(String path, String relativePath) {
    String[] pathParts = path.split("/");
    String[] relativeParts = relativePath.split("/");
    int length = pathParts.length;

    for (String relativePart : relativeParts) {
        if (relativePart.equals("..")) {
            if (length > 0) {
                length--;
            }
        } else if (relativePart.equals(".")) {
            continue;
        } else {
            pathParts[length++] = relativePart;
        }
    }

    StringBuilder result = new StringBuilder();
    for (int i = 0; i < length; i++) {
        if (i > 0) {
            result.append("/");
        }
        result.append(pathParts[i]);
    }

    return result.toString();
}

String applyRelativePath(String path, String relativePath) {
    // Normalize the input paths by replacing backslashes with forward slashes
    path = path.replace('\\', '/');
    relativePath = relativePath.replace('\\', '/');

    // Split the paths into components
    String[] pathComponents = path.split("/");
    String[] relativePathComponents = relativePath.split("/");

    // Use a stack to build the final path
    Stack<String> pathStack = new Stack<>();
    for (String component : pathComponents) {
        if (!component.isEmpty()) {
            pathStack.push(component);
        }
    }

    for (String component : relativePathComponents) {
        if (component.isEmpty() || component.equals(".")) {
            continue;
        } else if (component.equals("..")) {
            if (!pathStack.isEmpty()) {
                pathStack.pop();
            }
        } else {
            pathStack.push(component);
        }
    }

    // Build the final path from the stack
    return String.join("/", pathStack);
}

